return ['domain'=>NULL,'plural-forms'=>'nplurals=4; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : n%10==0 || (n%10>=5 && n%10<=9) || (n%100>=11 && n%100<=14)? 2 : 3);','language'=>'ru_RU','project-id-version'=>'WPGlobus Multilingual','pot-creation-date'=>'2026-02-01 02:55+0000','po-revision-date'=>'2015-09-03 17:28+0000','messages'=>['Guide'=>'Инструкция','WPGlobus Help Desk'=>'Поддержка','Add-ons'=>'Расширения','Quick Start'=>'Быстрый Старт','FAQ'=>'ЧаВо','Attention: the Multibyte String PHP extension (`mbstring`) is not loaded!'=>'Внимание: расширение PHP Multibyte String (`mbstring`) не загружено!','The mbstring extension is required for the full UTF-8 compatibility and better performance. Without it, some parts of WordPress and WPGlobus may function incorrectly. Please contact your hosting company or systems administrator.'=>'Расширение mbstring необходимо для поддержки UTF-8 и для улучшенной производительности. Без этого расширения некоторые части ВордПресс и WPGlobus могут функционировать некорректно. Пожалуйста, сообщите вашему провайдеру или системному администратору (вебмастеру).','Go to WPGlobus Settings'=>'Перейдите в настройки WPGlobus','Easy as 1-2-3:'=>'Просто, как 1-2-3:','Go to WPGlobus admin menu and choose the countries / languages;'=>'Войдите в меню администратора WPGlobus и выберите страны и языки;','Enter the translations to the posts, pages, categories, tags and menus using a clean and simple interface.'=>'Введите переводы записей, страниц, категорий, меток и меню, используя простой и удобный интерфейс.','Switch languages at the front-end using a drop-down menu with language names and country flags.'=>'Переключайте языки, используя раскрывающееся меню с их названиями и флагами стран.','Links:'=>'Ссылки:','FAQs'=>'Вопросы и ответы','Contact Us'=>'Обратная связь','Please give us 5 stars!'=>'Пожалуйста, поставьте нам 5 звездочек!','WPGlobus does not translate texts automatically!'=>'WPGlobus не делает автоматические переводы текста!','There are many translation companies and individual translators who can help you write and proofread the texts.'=>'Вы можете воспользоваться услугами профессиональных переводчиков.','When you choose a translator, please look at their native language, country of residence, specialization and knowledge of WordPress.'=>'При выборе переводчика обратите внимание на родной язык, страну проживания, специализацию и знание ВордПресс.','Important notes:'=>'Важная информация:','WPGlobus only supports the localization URLs in the form of <code>example.com/xx/page/</code>. We do not plan to support subdomains <code>xx.example.com</code> and language queries <code>example.com?lang=xx</code>.'=>'WPGlobus поддерживает только локализацию URL-адреса в виде <code>example.com/xx/page/</code>. Мы не планируем поддерживать дочерние домены <code>xx.example.com</code> и языковые параметры в УРЛах <code>example.com?lang=xx</code>.','Some themes and plugins are <strong>not multilingual-ready</strong>.'=>'Некоторые темы и плагины <strong>не полностью поддерживают многоязычный режим</strong>.','They might display some texts with no translation, or with all languages mixed together.'=>'Они могут выводить на экран некоторые тексты без перевода, или смешивая разные языки.','Please contact the theme / plugin author. If they are unable to assist, consider %1$s hiring the WPGlobus Team %2$s to write a custom code for you.'=>'Пожалуйста, свяжитесь с авторами темы / плагина. Если они не могут помочь, рассмотрите возможность %1$s дать заказ команде разработчиков WPGlobus %2$s на написание кода специально для вас.','Language was set on your profile page'=>'Язык указан на странице вашего профиля','Add'=>'Добавить','Multilingual WordPress'=>'ВордПресс - на всех языках!','WPGlobus is a family of WordPress plugins assisting you in making multilingual WordPress blogs and sites.'=>'WPGlobus - это коллекция плагинов ВордПресс для создания многоязычных сайтов.','Remove the WPGlobus settings (not recommended)'=>'Удалить настройки WPGlobus (не рекомендуется)','note that WPGlobus extensions settings will be removed also!'=>'настройки расширений WPGlobus будут тоже удалены','Clean-up Tool'=>'Программа очистки','WARNING: this operation is non-reversible. It is strongly recommended that you backup your database before proceeding.'=>'Предупреждение: эта операция является необратимой. Настоятельно рекомендуем сделать резервную копию базы данных перед продолжением.','This tool should be used only if you plan to completely uninstall WPGlobus. By running it, you will remove ALL translations you have entered to your post, pages, etc., keeping only the MAIN language texts. Please make sure that all entries have some content in the main language. Otherwise, you might end up with empty titles, no content, no excerpts, blank comments and so on.'=>'Эту программу следует использовать только, если вы планируете полностью удалить WPGlobus. Программа удалит все переводы в записях, страницах, и т.п., сохраняя только тексты на основном языке. Пожалуйста, убедитесь, что во всех записях присутствует контент на основном языке. В противном случае вы обнаружите пустые заголовки, отсутствие контента страниц, пустые комментарии и тому подобное.','Make sure that your active theme does not have any code related to WPGlobus. Such code could be added by you or by a 3rd party developer. If that code runs without first verifying that WPGlobus is active, WordPress may die with a fatal error.'=>'Убедитесь в том что в вашей активной теме не останется кода связанного с WPGlobus, который мог быть добавлен вами или сторонним разработчиком. Если такой код использован без проверки активирован ли WPGlobus, то это может привести к неработоспособности всего сайта (белый экран смерти).','The main language is currently set to %1$s (%2$s). ALL TEXTS THAT ARE NOT IN %1$s WILL BE DELETED! To change the main language, please go to {{settings}}.'=>'В настройках WPGlobus указано, что основной язык - %1$s (%2$s). Все тексты, кроме %1$s будут удалены! Чтобы изменить основной язык, пожалуйста, перейдите в {{settings}}.','You are about to clean the content of the following database tables:'=>'Программа выполнит очистку следующих таблиц базы данных:','The operations log'=>'Журнал операций','We are going to write a detailed log of all the database changes performed. It should help in the case you need to restore something important. The log will be written to the file:'=>'Мы собираемся записать все изменения в базе данных в журнал. Он может помочь в случае, если вам потребуется восстановить что-то важное. Журнал будет записываться в файл:','Uncheck if you do not want to write the operations log (we recommend to keep it checked)'=>'Снимите флажок, если вы не хотите записывать операции в журнал (мы рекомендуем оставить запись включённой)','You have been warned...'=>'Вы уверены, что готовы продолжить?','Please confirm by checking the box below:'=>'Пожалуйста, подтвердите, установив флажок ниже:','I have read and understood everything written on this page. I am aware that by using this tool I may loose some content of my website. I have made a database backup and know how to restore it if necessary. I am fully responsible for the results.'=>'Мне понятно всё, что написано на этой странице. Я знаю, что в результате запуска Программы очистки я могу потерять некоторую часть контента моего веб-сайта. Мною выполнена резервная копия базы данных, и я знаю, как восстановить её в случае необходимости. Я полностью несу ответственность за результат.','YES, I CONFIRM'=>'ДА, Я ПОДТВЕРЖДАЮ','Process with the Clean-up'=>'Запустить программу очистки','Default'=>'По умолчанию','Section'=>'Раздел','Show all sections'=>'Показать все разделы','Check/Uncheck all'=>'Выбрать/отменить все','Save &amp; Reload'=>'Сохранить и перезагрузить','WPGlobus'=>'WPGlobus','You need to update WordPress to 4.5 or later to get Fields Settings section'=>'Этот раздел доступен в WordPress версии 4.5 и выше.','Fields Settings'=>'Настройки полей','WPGlobus Settings'=>'Настройки WPGlobus','Help'=>'Помощь','Languages'=>'Языки','Enabled Languages'=>'Установленные языки','These languages are currently enabled on your site.'=>'Эти языки включены в настоящее время на вашем сайте.','Choose a language you would like to enable.'=>'Выберите из списка язык, который вы хотите разрешить к использованию.','Press the [Save & Publish] button to confirm.'=>'Нажмите [Сохранить и опубликовать] для подтверждения.','or Add new Language %1$s here %2$s'=>'или добавьте новый язык %1$s здесь %2$s','Add Languages'=>'Добавить языки','Language Selector Mode'=>'Способ показа переключателей','Two-letter Code with flag (en, ru, it, etc.)'=>'Двухбуквенный код (en, ru, it, и т.п.) и флаг','Full Name (English, Russian, Italian, etc.)'=>'Полное название (English, Russian, Italian, и т.п.)','Full Name with flag (English, Russian, Italian, etc.)'=>'Полное название (English, Russian, Italian, и т.п.) и флаг','Flags only'=>'Только флаги','Choose the way language name and country flag are shown in the drop-down menu'=>'Выберите способ показа названий языков и флагов в навигационном меню','select navigation menu'=>'выберите навигационное меню','Language Selector Menu'=>'Навигационное меню','Choose the navigation menu where the language selector will be shown'=>'Выберите навигационное меню, в котором будет показан переключатель языков','No menus have been created yet. Create some.'=>'Ни одного меню ещё не создано. Создайте.','"All Pages" menus Language selector'=>'Переключатель языка в меню «Все страницы»','Adds language selector to the menus that automatically list all existing pages (using `wp_list_pages`)'=>'Добавить переключатель языка в меню, которые автоматически показывают список всех страниц (с использованием `wp_list_pages`)','Custom CSS'=>'Пользовательский CSS','Here you can enter the CSS rules to adjust the language selector menu for your theme. Look at the examples in the `style-samples.css` file.'=>'Сюда вы можете поместить набор правил CSS для тонкой настройки меню выбора языков. Примеры для стандартных тем можно найти в файле `style-samples.css`.','Post types'=>'Типы записей','Uncheck to disable WPGlobus'=>'Снимите флажок, чтобы отключить WPGlobus','Redirect'=>'Перенаправление','Choose the language automatically, based on:'=>'Выбрать язык автоматически, учитывая:','Preferred language set in the browser'=>'Язык, указанный как предпочтительный в настройках браузера','When a user comes to the site for the first time, try to find the best matching language version of the page.'=>'Когда посетитель попадает на сайт в первый раз, попытаться выбрать язык страницы автоматически.','Custom JS Code'=>'Пользовательский JS','Title'=>'Заголовок','(Paste your JS code here.)'=>'(Поместите сюда JS код.)','To add a Custom JS Code in Customizer, you need to upgrade WordPress to version 4.9 or later.'=>'Чтобы добавить Пользовательский JS в "Настройке", необходимо обновить ВордПресс до версии 4.9 или более поздней.','With your version of WordPress, please use the'=>'Для вашей версии ВордПресс, пожалуйста, перейдите сюда: ','WPGlobus Settings page'=>'Панель настроек WPGlobus','Label'=>'Метка','Description'=>'Описание','Here you can specify which fields should be considered multilingual by WPGlobus. To exclude a field, uncheck it and then press the button %s below.'=>'Здесь вы можете указать, какие поля считаются многоязычными и должны обрабатываться WPGlobus. Чтобы исключить поле, снимите отметку и нажмите кнопку %s внизу.','Thank you for installing WPGlobus!'=>'Спасибо за то, что вы установили плагин WPGlobus!','Read About WPGlobus'=>'Подробно о WPGlobus','Click the <strong>[Languages]</strong> tab at the left to setup the options.'=>'Настройки плагина находятся в разделе <strong>[Языки]</strong>.','Should you have any questions or comments, please do not hesitate to contact us.'=>'Если у вас есть вопросы или замечания, пожалуйста, обращайтесь к нам за поддержкой.','Sincerely Yours,'=>'С уважением,','The WPGlobus Team'=>'Команда WPGlobus','We would hate to see you go. If something goes wrong, do not uninstall WPGlobus yet. Please %1$stalk to us%2$s and let us help!'=>'Обнаружили проблему в WPGlobus? Не торопитесь удалять плагин. Пожалуйста %1$sобратитесь к нам%2$s и позвольте вам помочь!','Please note that if you deactivate WPGlobus, your site will show all the languages together, mixed up. You will need to remove all translations, keeping only one language.'=>'Пожалуйста, обратите внимание: если вы отключите WPGlobus, ваш сайт будет показывать все языки одновременно. Вам будет необходимо удалить все переводы, сохранив только один язык.','If there are just a few places, you should edit them manually. To automatically remove all translations at once, you can use the %s. WARNING: The clean-up operation is irreversible, so use it only if you need to completely uninstall WPGlobus.'=>'Если есть лишь несколько мест с переводами, стоит отредактировать их вручную. Чтобы автоматически удалить все переводы сразу, можно использовать %s. Предупреждение: операция очистки является необратимой, так что используйте её, только если вы решили окончательно удалить WPGlobus.','%1$sClean-up Tool%2$s'=>'%1$sПрограмму очистки%2$s','Sorry, WPGlobus customizer doesn\'t support current theme %s.'=>'Извините, тема %s не поддерживается WPGlobus.','Please use %1$sWPGlobus options page%2$s instead.'=>'Пожалуйста, используйте %1$sпанель настроек WPGlobus%2$s.','Expand/Shrink'=>'Развернуть/Свернуть','WPGlobus News'=>'Новости WPGlobus','Options updated'=>'Настройки сохранены','Please enter a language code!'=>'Пожалуйста, введите код языка!','Language code already exists!'=>'Такой код языка уже существует!','Please specify the language flag!'=>'Пожалуйста, укажите флаг для языка!','Please enter the language name!'=>'Пожалуйста, введите название языка!','Please enter the language name in English!'=>'Пожалуйста, введите название языка по-английски!','Please enter the locale!'=>'Пожалуйста, введите локаль!','Add Language'=>'Добавить язык','Delete Language'=>'Удалить язык','Edit Language'=>'Изменить язык','Language Code'=>'Код языка','2-Letter ISO Language Code for the Language you want to insert. (Example: en)'=>'Двухбуквенная ISO-кодировка языка, который вы хотите добавить (Пример: en)','Language flag'=>'Флаг','Name'=>'Название','The name of the language in its native alphabet. (Examples: English, Русский)'=>'Название на языке оригинала. (Пример: English, Русский)','Name in English'=>'Название по-английски','The name of the language in English'=>'Название языка по-английски','Locale'=>'Локаль','PHP/WordPress Locale of the language. (Examples: en_US, ru_RU)'=>'PHP/WordPress локаль языка. (Пример: en_US, ru_RU)','Are you sure you want to delete?'=>'Удалить? Вы уверены?','Save Changes'=>'Сохранить изменения','Back to the WPGlobus Settings'=>'Вернуться к настройкам WPGlobus','Current Version'=>'Текущая версия','Premium add-on'=>'Платное расширение','Installed'=>'Установлен','Get it now!'=>'Установить!','If you have already purchased a WPGlobus premium extension, please read %1$sthe installation instructions here%2$s'=>'Если вы уже купили какое-либо расширение, то прочтите %1$sУстановка платных расширений WPGlobus%2$s','Widgets with WPGlobus'=>'Виджеты с WPGlobus','Help Desk'=>'Поддержка','Email not sent. Please fill in the entire form.'=>'Сообщение не отправлено. Пожалуйста, заполните правильно все поля.','Email not sent. Please verify that your name and email are entered correctly.'=>'Сообщение не отправлено. Убедитесь, что ваше имя и адрес email заполнены без ошибок.','Email sent.'=>'Сообщение отправлено.','Thank you for using WPGlobus!'=>'Спасибо за то, что вы выбрали WPGlobus!','Our Support Team is here to answer your questions or concerns.'=>'Наша Служба Поддержки постарается ответить на любой из ваших вопросов.','To help us serve you better:'=>'Чтобы ускорить поиск решения вашей проблемы:','Please check if the problem persists if you switch to a standard WordPress theme.'=>'Пожалуйста, убедитесь, что проблема сохраняется, если вы переключитесь на стандартную тему ВордПресс.','Try deactivating other plugins to see if any of them conflicts with WPGlobus.'=>'Попробуйте деактивировать плагины, чтобы убедиться, не конфликтует ли какой-то из них с WPGlobus.','Please fill in and submit the contact form:'=>'Пожалуйста, заполните и отправьте форму:','Please make sure the email address is correct.'=>'Внимательно проверьте адрес email.','Subject'=>'Тема сообщения','Short description of the problem'=>'Короткое описание проблемы','Detailed description'=>'Детальное описание','Technical Information'=>'Техническая информация','This information helps us to find the problem source'=>'Эта информация поможет нам в поиске источника проблемы','Alternatively, please email %s. Do not forget to copy and paste the technical information to your email message.'=>'Вы также можете отправить нам сообщение на %s. Не забудьте скопировать техническую информацию в текст вашего сообщения.','Go to WPGlobus Plus Options page'=>'Перейдите к настройкам WPGlobus Плюс','To translate permalinks, please activate the module Slug.'=>'Для перевода ссылок необходимо активировать модуль УРЛ.','To use module Publish, please activate it.'=>'Чтобы использовать модуль Publish, его необходимо активировать.','WPGlobus Recommends:'=>'WPGlobus рекомендует:','WPGlobus for WooCommerce'=>'WPGlobus для WooCommerce','Translate product titles and descriptions, product categories, tags and attributes.'=>'Переведите названия и описания товаров, категорий, свойств и меток.','Get it now:'=>'Установите прямо сейчас:','WooCommerce Multi-Currency'=>'Мультивалютность для WooCommerce','Accept multiple currencies in your online store!'=>'Принимайте оплату в нескольких валютах!','Check it out:'=>'Информация - здесь:','For %1$s to work correctly, PHP version %2$s or later is required.'=>'Для корректной работы %1$s нужно использовать PHP версии %2$s или выше.','The PHP version on your server is %3$s.'=>'Используемая вашим сервером версия PHP - %3$s.','For %1$s to work correctly, WordPress version %2$s or later is required.'=>'Для корректной работы %1$s нужно использовать WordPress версии %2$s или выше.','Save draft before using extra language.'=>'Сохраните черновик перед переключением на другой язык.','Builder'=>'Билдер','Сompatibility Settings'=>'Совместимость','ON'=>'ВКЛ','Turn off'=>'Выключить','OFF'=>'ВЫКЛ','Turn on'=>'Включить','Elementor'=>'Elementor','WPGlobus languages'=>'Языки WPGlobus','current'=>'текущий','WPGlobus provides multilingual support for Elementor only when the option %1$s%2$s%3$s is set to %4$s.'=>'WPGlobus поддерживает мультиязычные страницы для Elementor только с опцией %1$s%2$s%3$s установленной в %4$s.','Before switching the language, please save draft or publish.'=>'Опубликуйте или сохраните черновик перед переключением на другой язык.','filter__seo_meta_box_titlefor'=>'для','Page is being reloaded. Please wait...'=>'Страница перезагружается. Подождите...','Before switching the language, please save draft or publish, then reload page.'=>'Опубликуйте или сохраните черновик перед переключением на другой язык. Затем перезагрузите страницу.','WPGlobus provides multilingual support for Elementor only when the option `CSS Print Method` is set to `External File`.'=>'WPGlobus обеспечивает мультиязычную поддержку Elementor только если `CSS Print Method` установлен в `External File`.','Open Elementor Settings page'=>'Настройки Elementor','WPGlobus widget'=>'WPGlobus виджет','Add language switcher'=>'Добавить переключатель языка','Flags'=>'Флаги','List'=>'Список','List with flags'=>'Список с флажками','Select'=>'Select','Select with language code'=>'Select с кодом языка','Dropdown'=>'Выпадающее меню','Dropdown with flags'=>'Выпадающее меню с флагами','Selector type'=>'Способ выбора языка','You cannot disable the main language.'=>'Нельзя отключить основной язык.','*) Available after the menu is saved.'=>'*) Доступно после сохранения меню.','About'=>'О нас','Enter title here'=>'Введите заголовок','You must enable Pretty Permalinks to use WPGlobus.'=>'Чтобы использовать плагин WPGlobus, необходимо включить ЧПУ - постоянные ссылки.','Please go to Settings > Permalinks > Common Settings and choose a non-default option.'=>'Пожалуйста, перейдите в меню Настройки > Постоянные ссылки и поменяйте структуру ссылок в разделе "Общие настройки".','Language Selector Menu Style'=>'Стиль меню выбора языка','WPGlobus Plus'=>'WPGlobus Плюс','Drop-down languages menu or Flat (in one line)'=>'Показать список языков в виде выпадающего меню или в одну строку','Do not change'=>'Ничего не менять','Drop-down (vertical)'=>'Выпадающее меню','Flat (horizontal)'=>'В одну строку','If you see this message then your browser may not display the WPGlobus Settings panel properly. Please try another browser.'=>'Ваш браузер показывает панель настроек WPGlobus некорректно. Обновите версию браузера или попробуйте другой.','Сompatibility'=>'Совместимость','Click the %1$s[Languages]%2$s tab at the left to setup the options.'=>'Основные настройки плагина находятся в разделе %1$s[Языки]%2$s.','Use the %1$s[Languages Table]%2$s section to add a new language or to edit the language attributes: name, code, flag icon, etc.'=>'Используйте раздел %1$s[Таблица языков]%2$s для того чтобы добавить язык или отредактировать аттрибуты (название, код, флаг и т.п.)','Important notes'=>'Важные уведомления','%1$sBuilder mode%2$s: WPGlobus turns this mode on automatically when it discovers any of the plugins/add-ons listed on the %1$s[%3$s]%2$s tab.'=>'%1$sBuilder mode%2$s: WPGlobus автоматически входит в этот режим, когда обнаруживает какие-либо плагины/надстройки, перечисленные на вкладке %1$s[%3$s]%2$s.','%1$sStandard/Classic mode%2$s: is used when there are no plugins `Builder` or if you explicitly turned off builder support on the %1$s[%3$s]%2$s tab.'=>'%1$sStandard/Classic mode%2$s: используется, когда нет плагинов `Builder` или если вы явно отключили поддержку компоновщика на вкладке %1$s[%3$s]%2$s.','The %1$sBuilder mode%2$s is turned OFF by default for all custom post types (CPT).'=>'Для всех пользовательских типов постов (CPT) %1$sBuilder mode%2$s отключен по умолчанию.','To turn on the %1$sBuilder mode%2$s for specific post types, please visit the %1$s[%3$s]%2$s tab.'=>'Чтобы включить поддержку %1$sBuilder mode%2$s для определённого типа постов перейдите на вкладку %1$s[%3$s]%2$s.','Welcome!'=>'Добро пожаловать!','Deactivating / Uninstalling'=>'Деактивация / Деинсталляция','Uninstall'=>'Деактивация','All add-ons'=>'Все расширения','Mobile Menu'=>'Мобильное Меню','Language Widgets'=>'Языки для виджетов','We Recommend...'=>'Рекомендуем...','Our premium add-on, WPGlobus Plus, will add several features to your website, such as:'=>'Расширение WPGlobus-Плюс позволит:','- Ability to write a post in one language and immediately publish it, not waiting for the translation to other languages;'=>'-Возможность написать сообщение на одном языке и немедленно опубликовать его, не дожидаясь их перевода на другие языки;','- Set different URLs for each translation;'=>'- Перевести УРЛы (постоянные ссылки) на различные языки;','- In Yoast SEO, set the focus keyword and do the Page Analysis separately for each translation;'=>'- В плагине Yoast SEO проверять ключевые слова и выполнять анализ текста для каждого языка;','- and more...'=>'- и много дополнительных возможностей...','Click here to download'=>'Нажмите здесь чтобы установить','Thanks for installing WPGlobus! Now you have a multilingual website and can translate your blog posts and pages to many languages.'=>'Спасибо за установку WPGlobus! Теперь у вас есть многоязычный веб-сайт, и вы можете перевести записи в блоге и страницы на несколько языков.','The next step is to translate your WooCommerce-based store!'=>'Следующий шаг - сделать мультиязычным ваш онлайн магазин!','With the WPGlobus for WooCommerce premium add-on, you will be able to translate product titles and descriptions, categories, tags and attributes.'=>'С помощью расширения WPGlobus для WooCommerce вы сможете перевести названия и описания товаров, категорий, свойств и меток.','Multi-currency'=>'Мультивалютность','Your WooCommerce-powered store is set to show prices and accept payments in a single currency only.'=>'Ваш магазин WooCommerce настроен на показ цен в одной валюте.','With WPGlobus, you can add multiple currencies to your store and charge UK customers in Pounds, US customers in Dollars, Spanish clients in Euros, etc. Accepting multiple currencies will strengthen your competitive edge and positioning for global growth!'=>'С помощью WPGlobus вы сможете автоматически пересчитывать цены по курсу и показывать клиентам привычную им валюту.','The WPGlobus Multi-Currency premium add-on provides switching currencies and re-calculating prices on-the-fly.'=>'Расширение WPGlobus-мультивалютность позволяет переключаться между валютами, автоматически пересчитывая цены.','WPGlobus Premium Add-ons'=>'Платные расширения','We have written several Premium add-ons for WPGlobus. With those add-ons, you will be able to:'=>'Мы написали несколько премиальных расширений для WPGlobus. С их помощью вы сможете:','<strong>Translate URLs</strong> (/my-page/ translates to /fr/ma-page, /es/mi-pagina and so on);'=>'<strong>Перевести УРЛы</strong> (/my-page/ станет /fr/ma-page/, /ru/моя-страница/ и так далее);','Postpone translation to some languages and <strong>publish only the translated texts</strong>;'=>'Отложить перевод на некоторые языки и <strong>опубликовать только переведенные тексты</strong>;','Maintain <strong>separate menus and widgets for each language</strong>;'=>'Поддерживать <strong>раздельные меню и виджеты для каждого языка</strong>;','<strong>Translate WooCommerce</strong> products and taxonomies;'=>'<strong>Перевести товары и категории WooCommerce</strong>;','Enter separate focus keywords for each language in the <strong>Yoast SEO</strong>;'=>'Проверять ключевые слова раздельно для каждого языка в <strong>Yoast SEO</strong>;','...and more.'=>'...и не только это.','Click here to visit the WPGlobus Store'=>'Посетите наш магазин','Select a language'=>'Выберите язык','Place the %1$smain language%2$s of your site at the top of the list by dragging the %3$s icons.'=>'Поместите %1$sосновной язык%2$s вашего сайта в верхней части списка, передвигая иконки %3$s.','%1$sUncheck%2$s the languages you do not plan to use.'=>'%1$sСнимите флажок%2$s с языков, которые вы не планируете использовать.','%1$sAdd%2$s more languages using the section below.'=>'%1$sДобавьте%2$s дополнительные языки, используя раздел ниже.','When done, click the [Save Changes] button.'=>'Когда закончите, нажмите кнопку [Сохранить изменения].','Press the %s button to confirm.'=>'Нажмите кнопку %s для подтверждения.','-- none --'=>'-- не показывать --','All menus'=>'Все меню','Instructions:'=>'Инструкции:','(Found in some themes)'=>'(Используется в некоторых темах)','Enable'=>'Включить','Languages table'=>'Таблица языков','Use this table to add, edit or delete languages.'=>'Используйте эту таблицу, чтобы добавлять, удалять или редактировать языки.','NOTE: you cannot remove the main language.'=>'ВНИМАНИЕ: язык по умолчанию не может быть удален.','WPGlobus is enabled on these Post Types'=>'WPGlobus активен в этих типах записей','Uncheck to disable'=>'Снимите флажок, чтобы отключить WPGlobus','Please note that there are post types, which status is managed by other plugins and cannot be changed here.'=>'Внимание: некоторые типы записей управляются другими плагинами и поэтому не могут контролироваться в этой панели настроек.','Post Types'=>'Типы записей','You should put here only the code provided by WPGlobus Support. Do not write anything else in the sections below as it might break the functionality of your website!'=>'Пожалуйста, используйте эти поля только для кода, который предоставлен службой поддержки WPGlobus. Не записывайте сюда ничего другого, поскольку это может нарушить работу вашего сайта!','Custom Code'=>'Добавьте JS/CSS','Enabled'=>'Разрешена','Builders support'=>'Поддержка конструкторов страниц (Builders)','Builder mode is enabled on these Post Types'=>'Режим `Builder` активен для этих типов записей','Use block editor on the Widgets page'=>'Использовать редактор блоков на странице Виджеты','You cannot use block editor on the Widgets page because your theme disabled it.'=>'Вы не можете использовать редактор блоков на странице Виджеты, так как его поддержка отключена в теме.','Block Editor'=>'Редактор блоков','Block Editor Options'=>'Настройки редактора блоков','With the current settings, you will see the following lines in the section HEAD of your site pages'=>'С текущими настройками вы увидите эти строки в секции head ваших страниц','(example for two languages)'=>'(пример для двух языков)','Tell search engines about localized versions of your pages using the hreflang tag'=>'Сообщите поисковикам о наличии локализованных версий страниц с помощью тега hreflang','Output the hreflang tag as'=>'Выводить код hreflang как','Language- and region-specific (en-US, ru-RU, etc.)'=>'Язык и регион в формате en-US, ru-RU, etc.','Language- and region-specific (en-us, ru-ru, etc.)'=>'Язык и регион в формате en-us, ru-ru, etc.','Language code only (en, ru, etc.)'=>'Только код языка (en, ru, etc.)','Use the code `x-default` for the main language'=>'Использовать код `x-default` для языка по умолчанию','Multilingual SEO'=>'Многоязычный SEO','Multilingual SEO Options'=>'Настройки многоязычного SEO','With WPGlobus, you can get translations for posts and pages using REST API.'=>'WPGlobus позволяет получать переводы постов и страниц используя REST API.','Go to %1$s%2$s%3$s to see the content in language: %4$s.'=>'Перейдите по ссылке %1$s%2$s%3$s для получения данных на языке: %4$s.','For demonstration, you can try the first post that WordPress creates at the initial installation.'=>'В качестве примера можно использовать первый пост который создаётся при установке WordPress.','Please read the %1$sWordPress REST API documentation%2$s for more information.'=>'Для получения подробной информации обратитесь к %1$sофициальной документации%2$s.','In the REST API response, you can find the %1$stranslation%2$s field, which shows whether translations exist for the fields %1$stitle%2$s, %1$scontent%2$s and %1$sexcerpt%2$s or not, for each language. See the screenshot below:'=>'В ответе REST API вы найдёте поле %1$stranslation%2$s, которое даёт возможность проверить, существуют ли переводы полей %1$stitle%2$s, %1$scontent%2$s и %1$sexcerpt%2$s для каждого языка (см.скриншот).','Description:'=>'Описание:','REST API'=>'REST API','Translate strings'=>'Переводы строк','item'=>'запись','items'=>'записей','Code'=>'Код','Edit'=>'Изменить','Delete'=>'Удалить','File'=>'Файл','Flag'=>'Флаг','Language name'=>'Название языка','English language name'=>'Название языка по-английски','No items found'=>'Нет записей','Add new Language'=>'Добавить новый язык','No items of this type were found.'=>'Список пуст.','Select an item'=>'Выберите из списка','Multilingual support of this add-on is currently in Beta stage.'=>'Предоставляется с целью тестирования и выявления возможных ошибок.','We do not recommend using it on production sites.'=>'Не рекомендуется использовать на рабочих сайтах.','WordPress version'=>'Версия WordPress','In the WordPress core'=>'В ядре WordPress','Core'=>'Ядро','Current version'=>'Установленная версия','Stage'=>'Готовность','Status'=>'Статус','Block editor'=>'Редактор блоков','production'=>'production','List of supported add-ons'=>'Список поддерживаемых расширений','Add-on'=>'Расширение','Supported minimum version'=>'Минимальная поддерживаемая версия','Not installed'=>'Не установлено','Installed, inactive'=>'Установлено, не активно','Active'=>'Активно','WPGlobus Customizer is integrated into the Customize Theme panel'=>'WPGlobus Customizer работает с настройщиком тем','However, some themes do not follow all WordPress standards strictly.'=>'Однако, следует иметь ввиду, что не все темы следуют стандартам WordPress.','WPGlobus Customizer may behave incorrectly with those themes.'=>'Поэтому возможна некорректная работа настройщика и WPGlobus Customizer.','To avoid conflicts, you can switch the WPGlobus Customizer off:'=>'Чтобы избежать некорректной работы WPGlobus Customizer, его можно отключить:','Below is the list of themes that do not support the WPGlobus Customizer. With those themes, WPGlobus Customizer is switched off by default'=>'Список тем, для которых по умолчанию не будет загружен WPGlobus Customizer:','The currently active theme is'=>'Cейчас активна тема','In the current version, WPGlobus Customizer does not support'=>'В текущей версии WPGlobus Customizer не поддерживает','translation of the navigation menus'=>'перевод пунктов навигационного меню','to translate, please go to'=>'для перевода перейдите на страницу','Go to Customizer'=>'Открыть настройку тем','is undefined'=>'не определена','is set to'=>'установлена в','by adding to the file wp-config.php'=>'добавлением в файл wp-config.php строки','now'=>'сейчас','We rely on your support!'=>'Спасибо за поддержку!','Please consider a small donation to support the future development.'=>'Ваше пожертвование будет использовано для дальшейшего развития и улучшения плагина.','Thank you!'=>'С благодарностью!','WPGlobus Plus!'=>'WPGlobus Плюс!','Advanced features and tweaks: URL translation, multilingual SEO analysis, separate publishing and more! '=>'Расширенные функции и настройки: переводы УРЛов, многоязычный SEO анализ, раздельная публикация и многое другое! ','Get WPGlobus Plus now!'=>'Установите WPGlobus Плюс прямо сейчас!','Use as multilingual with %1$sWPGlobus%2$s'=>'Использовать как многоязычное с %1$sWPGlobus%2$s','Multilingual'=>'Многоязычное','Bulk editing of the multilingual titles and descriptions is not supported by the current version.'=>'Текущая версия не поддерживает возможность массового редактирования многоязычных заголовков и описаний.','Therefore, to avoid any data loss, we do not recommend using this.'=>'Поэтому не рекомендуем использовать этот режим во избежание потери данных.','WPGlobus warning: '=>'Предупреждение WPGlobus: ']];